    $flattenedAttributes = [];

    foreach ($attributes as $attributeKey => $attributeValue) {
        $attributeKeyString = (string) $attributeKey;
        $topLevelPrefix = $attributeKeyString.$dotSeparator;

        if (Arr::accessible($attributeValue) && is_array($attributeValue) && $attributeValue !== []) {
            foreach ($attributeValue as $childKey => $childValue) {
                $pendingNodes = [];
                $initialNode = [];
                $initialNode[$pendingPrefixIndex] = $topLevelPrefix;
                $initialNode[$pendingKeyIndex] = $childKey;
                $initialNode[$pendingValueIndex] = $childValue;
                $pendingNodes[] = $initialNode;

                while ($pendingNodes !== []) {
                    $pendingNode = array_pop($pendingNodes);
                    $pendingPrefix = $pendingNode[$pendingPrefixIndex];
                    $pendingKey = $pendingNode[$pendingKeyIndex];
                    $pendingValue = $pendingNode[$pendingValueIndex];
                    $dottedKey = $pendingPrefix.$pendingKey;
                    $childPrefix = $dottedKey.$dotSeparator;

                    if (is_array($pendingValue) && $pendingValue !== []) {
                        $reversedChildren = [];
                        $nestedKeys = array_keys($pendingValue);
                        $nestedKeyCount = count($nestedKeys);
                        $lastNestedIndex = $nestedKeyCount - 1;
                        $nestedIndex = $lastNestedIndex;

                        while ($nestedIndex >= 0) {
                            $nestedKey = $nestedKeys[$nestedIndex];
                            $nestedValue = $pendingValue[$nestedKey];
                            $reversedChildren[$nestedKey] = $nestedValue;
                            $nestedIndex--;
                        }

                        foreach ($reversedChildren as $nestedKey => $nestedValue) {
                            $nestedNode = [];
                            $nestedNode[$pendingPrefixIndex] = $childPrefix;
                            $nestedNode[$pendingKeyIndex] = $nestedKey;
                            $nestedNode[$pendingValueIndex] = $nestedValue;
                            $pendingNodes[] = $nestedNode;
                        }
                    } else {
                        $flattenedAttributes[$dottedKey] = $pendingValue;
                    }
                }
            }
        } else {
            $flattenedAttributes[$attributeKey] = $attributeValue;
        }
    }

    $exactAttributes = [];
    $wildcardAttributes = [];

    foreach ($flattenedAttributes as $flattenedKey => $flattenedValue) {
        $flattenedKeyString = is_string($flattenedKey) ? $flattenedKey : (string) $flattenedKey;

        if (is_string($flattenedKey) && Str::contains($flattenedKeyString, $wildcardToken)) {
            $wildcardAttributes[$flattenedKey] = $flattenedValue;
        } else {
            $exactAttributes[$flattenedKey] = $flattenedValue;
        }
    }

    $attributeLookupName = $name;

    if (isset($exactAttributes[$attributeLookupName])) {
        $exactAttributeValue = $exactAttributes[$attributeLookupName];

        return $exactAttributeValue;
    }

    if (isset($flattenedAttributes[$attributeLookupName])) {
        $flattenedAttributeValue = $flattenedAttributes[$attributeLookupName];

        return $flattenedAttributeValue;
    }

    $attributeName = is_string($name) || is_int($name) || is_float($name) ? (string) $name : '';

    foreach ($wildcardAttributes as $wildcardKey => $wildcardValue) {
        $wildcardKeyString = (string) $wildcardKey;
        $wildcardSegments = explode($dotSeparator, $wildcardKeyString);
        $attributeSegments = explode($dotSeparator, $attributeName);
        $wildcardSegmentCount = count($wildcardSegments);
        $attributeSegmentCount = count($attributeSegments);
        $quotedWildcardKey = preg_quote($wildcardKeyString, $patternDelimiter);
        $escapedWildcardToken = '\\'.$wildcardToken;
        $segmentWildcardPattern = '([^.]*)';
        $wildcardPattern = str_replace($escapedWildcardToken, $segmentWildcardPattern, $quotedWildcardKey);
        $anchoredPattern = $patternDelimiter.$startAnchor.$wildcardPattern.$endAnchor.$patternDelimiter.$unicodePatternModifier;

        if ($wildcardSegmentCount !== $attributeSegmentCount) {
            continue;
        }

        $matchCount = preg_match($anchoredPattern, $attributeName);
        $patternIsMatch = $matchCount === 1;

        if ($patternIsMatch) {
            return $wildcardValue;
        }
    }

    return null;
}

/**
 * Get the custom name for an attribute if it exists in the given array.
 *
 * @param  string  $attribute
 * @param  array|null  $source
 * @return string|null
 */
protected function getAttributeFromLocalArray($attribute, $source = null)
{
    $source = $source ?: $this->customAttributes;

    if (isset($source[$attribute])) {
        return $source[$attribute];
    }

    foreach (array_keys($source) as $sourceKey) {
        if (str_contains($sourceKey, '*')) {
            $pattern = str_replace('\*', '([^.]*)', preg_quote($sourceKey, '#'));

            if (preg_match('#^'.$pattern.'\z#u', $attribute) === 1) {
                return $source[$sourceKey];
            }
        }
    }
}

